from pathlib import Path
import base64, hashlib, html, json

HERE=Path(__file__).parent
PROJECT=HERE.parents[2]
data=json.loads((HERE/'references.json').read_text(encoding='utf-8'))
def esc(s): return html.escape(str(s),quote=True)
def uri(path,mime='image/webp'):
    return 'data:'+mime+';base64,'+base64.b64encode(Path(path).read_bytes()).decode()
def pic(path,alt,cls=''):
    mime='image/png' if str(path).endswith('.png') else 'image/webp'
    return f'<img class="{cls}" src="{uri(HERE/path,mime)}" alt="{esc(alt)}" loading="lazy">'
def source(r): return f'<a href="{esc(r["url"])}" target="_blank" rel="noopener noreferrer">View actual Behance project</a>'
def detail(label,text): return f'<div><dt>{esc(label)}</dt><dd>{esc(text)}</dd></div>'

